import { Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { AlertService } from 'src/app/services/alert.service';
import { EmisService } from 'src/app/services/emis/emis.service';
import { UserSessionService } from 'src/app/services/usersession.service';

@Component({
  selector: 'app-otp-submission',
  templateUrl: './otp-submission.page.html',
  styleUrls: ['./otp-submission.page.scss'],
})
export class OtpSubmissionPage implements OnInit {
  emis_usertype: any;
  data: any;
  otp: any;
  emisName: any;

  constructor(public router:Router,private userSessionService: UserSessionService,private route: ActivatedRoute,
    private emisService: EmisService,private alertService: AlertService) { }

  ngOnInit() {
  }

  ionViewDidEnter() {
    this.otp = "";
    this.emis_usertype = this.userSessionService.emis_usertype()
    this.emisName = this.userSessionService.emis_username()
    this.route.queryParams.subscribe((params) => {
      this.data = JSON.parse(params['data']);
    })
    
  }
  backBtn(){
    this.router.navigate(["/tabs/pums-session-details"]) 
  }

  otpdata(event){
    console.log(event.detail.value,"oooo")
    this.otp = event.detail.value
  }

  otpSave(){

    if(this.data.StartStatus == 1){
      let data = {
        "IndexId": this.data.IndexId,
        "EndOtp": this.otp
      }
  
      this.emisService.ArpVerifyOtp({"records":data}).subscribe(res => {
        if(res.dataStatus){
          this.alertService.success(res.message)
          this.router.navigate(["/tabs/my-schools"])
        }
        else{
          this.alertService.error(res.message)
        }
      });
    }
    else{
      let data = {
        "IndexId": "",
        "SchlId": this.data.school_id,
        "ArpId": this.emisName,
        "BatchId": this.data.batch_id,
        "GroupId": this.data.id,
        "Session": this.data.session,
        "StartOtp": this.otp
      }
  
      this.emisService.ArpVerifyOtp({"records":data}).subscribe(res => {
        if(res.dataStatus){
          this.alertService.success(res.message)
          this.router.navigate(["/tabs/my-schools"])
        }
        else{
          this.alertService.error(res.message)
        }
      });
    }
    
  }
}
